findings.recommendation:
Handle the string-body case (and defensively the object case as well). Two viable shapes:

```ts
} catch (err: unknown) {
  const opts = (err as { options?: { body?: unknown } })?.options
  if (opts) {
    if (typeof opts.body === 'string') {
      // ofetch serialised JSON body — the common case
      try {
        const parsed = JSON.parse(opts.body) as Record<string, unknown>
        if (parsed && typeof parsed === 'object' && 'token' in parsed) {
          opts.body = JSON.stringify({ ...parsed, token: '[redacted]' })
        }
      } catch {
        // Body is a string but not JSON — overwrite wholesale.
        opts.body = '[redacted]'
      }
    } else if (opts.body && typeof opts.body === 'object') {
      // Defensive: error thrown before serialisation (shouldn't happen with ofetch ≥1.5)
      opts.body = { ...(opts.body as Record<string, unknown>), token: '[redacted]' }
    }
  }
  throw err
}
```

Or, simpler and strictly safer — just nuke the body field, since the caller cannot use it for anything anyway:

```ts
} catch (err: unknown) {
  const opts = (err as { options?: { body?: unknown } })?.options
  if (opts && 'body' in opts) opts.body = '[redacted]'
  throw err
}
```

Add a unit test that asserts `JSON.stringify(thrownError.options.body).includes('<the-token>') === false` to lock this down — the current code passes type checks but fails the actual security invariant.
